// International parcel rates. Prices are in cents.
// Base price covers the first kg; each started 100 g beyond that adds a step.
export const ZONES = {
  EU: { baseCents: 1500, stepCents: 80 },
  WORLD: { baseCents: 2500, stepCents: 140 },
};

export class RestrictedItemError extends Error {
  constructor(message = "lithium items cannot be shipped internationally") {
    super(message);
    this.name = "RestrictedItemError";
  }
}

export function internationalQuote(weightKg, zone, items = []) {
  if (!(weightKg > 0)) throw new RangeError("weight must be positive");
  if (!Object.hasOwn(ZONES, zone)) throw new RangeError(`unknown zone: ${zone}`);
  if ((items ?? []).some((item) => item?.lithium === true)) throw new RestrictedItemError();

  // Integer grams avoid float error (e.g. (1.3 - 1) * 10 is not exactly 3).
  let grams = Math.round(weightKg * 1000);
  // Above 2 kg, round up to the next 0.5 kg before pricing.
  if (grams > 2000) grams = Math.ceil(grams / 500) * 500;

  const { baseCents, stepCents } = ZONES[zone];
  const steps = grams > 1000 ? Math.ceil((grams - 1000) / 100) : 0;
  return baseCents + steps * stepCents;
}
EOF
