const SMS_LIMIT = 160;
const VALID_PHONE = /^\+\d{8,15}$/;

// Cuts `text` to the SMS limit by code points, ending with "…" when cut.
function truncate(text) {
  const chars = [...text];
  if (chars.length <= SMS_LIMIT) return text;
  return chars.slice(0, SMS_LIMIT - 1).join("") + "…";
}

// Sends `message` to `user` and returns the ids of the messages sent.
// Users: { id, email, phone?, prefers? }. Users preferring "sms" with a valid phone get a
// text; otherwise (no or invalid phone) they get an email.
export function notify(user, message) {
  if (user.prefers === "sms" && VALID_PHONE.test(user.phone ?? "")) {
    return [sendSms(user.phone, truncate(message))];
  }
  const id = sendEmail(user.email.trim().toLowerCase(), message);
  return [id];
}
