import { lineCents } from "./invoice.js";

const isGiftCard = (line) => line.sku.startsWith("GC-");

// Order total in cents with the volume discount applied to non-gift-card lines only.
export function discountedTotalCents(order) {
  let units = 0;
  let subtotal = 0;
  let giftCards = 0;
  for (const line of order.lines) {
    if (isGiftCard(line)) {
      giftCards += lineCents(line);
    } else {
      units += line.qty;
      subtotal += lineCents(line);
    }
  }
  const rate = units >= 100 ? 0.1 : units >= 50 ? 0.05 : 0;
  return subtotal - Math.round(subtotal * rate) + giftCards;
}
